// Do not edit this file as it will be overwritten if HAMR codegen is rerun

use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_Input1: i32,
  pub api_Input2: i32,
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_Input1(container.api_Input1);
  put_Input2(container.api_Input2);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(
  Input1: i32,
  Input2: i32)
{
  put_Input1(Input1);
  put_Input2(Input2);
}

/// setter for IN DataPort
pub fn put_Input1(value: i32)
{
  *extern_api::IN_Input1.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_Input2(value: i32)
{
  *extern_api::IN_Input2.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_Output() -> i32
{
  return extern_api::OUT_Output.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}
